	filec := &embedded.EmbeddedFile{
		Filename:    "airgap-agent/init.sh",
		FileModTime: time.Unix(1774969763, 0),

		Content: string("#!/bin/sh\n# Script to detect Linux distribution and version\n# Used as a precursor for system-specific installations\n\n# Exit on error and print commands for debugging\nset -e\nset -x\n\n# Define user variable\nuser=\"$(id -un 2>/dev/null || true)\"\n\n# Check if a command exists\ncommand_exists() {\n    command -v \"$@\" > /dev/null 2>&1\n}\n\n# Detect the Linux distribution\nget_distribution() {\n    lsb_dist=\"\"\n    dist_version=\"\"\n    \n    # Every system that we officially support has /etc/os-release\n    if [ -r /etc/os-release ]; then\n        \n        lsb_dist=\"$(. /etc/os-release && echo \"$ID\")\"\n        \n        dist_version=\"$(. /etc/os-release && echo \"$VERSION_ID\")\"\n        lsb_dist=\"$(echo \"$lsb_dist\" | tr '[:upper:]' '[:lower:]')\"\n    else\n        echo \"Error: Unsupported Linux distribution! /etc/os-release not found.\"\n        exit 1\n    fi\n    \n    echo \"# Detected distribution: $lsb_dist (version: $dist_version)\"\n}\n\n# Check if this is a forked Linux distro\ncheck_forked() {\n    # Skip if lsb_release doesn't exist\n    if ! command_exists lsb_release; then\n        return\n    fi\n    \n    # Check if the `-u` option is supported\n    set +e\n    lsb_release -a > /dev/null 2>&1\n    lsb_release_exit_code=$?\n    set -e\n\n    # Check if the command has exited successfully, it means we're in a forked distro\n    if [ \"$lsb_release_exit_code\" = \"0\" ]; then\n        # Get the upstream release info\n        current_lsb_dist=$(lsb_release -a 2>&1 | tr '[:upper:]' '[:lower:]' | grep -E 'id' | cut -d ':' -f 2 | tr -d '[:space:]')\n        current_dist_version=$(lsb_release -a 2>&1 | tr '[:upper:]' '[:lower:]' | grep -E 'codename' | cut -d ':' -f 2 | tr -d '[:space:]')\n\n        # Print info about current distro\n        echo \"You're using '$current_lsb_dist' version '$current_dist_version'.\"\n        \n        # Check if current is different from detected (indicating a fork)\n        if [ \"$current_lsb_dist\" != \"$lsb_dist\" ] || [ \"$current_dist_version\" != \"$dist_version\" ]; then\n            echo \"Upstream release is '$lsb_dist' version '$dist_version'.\"\n        fi\n    else\n        # Additional checks for specific distros that might not be properly detected\n        if [ -r /etc/debian_version ] && [ \"$lsb_dist\" != \"ubuntu\" ] && [ \"$lsb_dist\" != \"raspbian\" ]; then\n            if [ \"$lsb_dist\" = \"osmc\" ]; then\n                # OSMC runs Raspbian\n                lsb_dist=raspbian\n            else\n                # We're Debian and don't even know it!\n                lsb_dist=debian\n            fi\n            # Get Debian version and map it to codename\n            dist_version=\"$(sed 's/\\/.*//' /etc/debian_version | sed 's/\\..*//')\"\n            case \"$dist_version\" in\n                14)\n                    dist_version=\"forky\"\n                ;;\n                13)\n                    dist_version=\"trixie\"\n                ;;\n                12)\n                    dist_version=\"bookworm\"\n                ;;\n                11)\n                    dist_version=\"bullseye\"\n                ;;\n                10)\n                    dist_version=\"buster\"\n                ;;\n                9)\n                    dist_version=\"stretch\"\n                ;;\n                8|'Kali Linux 2')\n                    dist_version=\"jessie\"\n                ;;\n                7)\n                    dist_version=\"wheezy\"\n                ;;\n            esac\n        elif [ -r /etc/redhat-release ] && [ -z \"$lsb_dist\" ]; then\n            lsb_dist=redhat\n            # Extract version from redhat-release file\n            dist_version=\"$(sed 's/.*release \\([0-9.]*\\).*/\\1/' /etc/redhat-release)\"\n        fi\n    fi\n}\n\n# Set up sudo command if necessary\nsetup_sudo() {\n    sh_c='sh -c'\n    if [ \"$user\" != 'root' ]; then\n        if command_exists sudo; then\n            sh_c='sudo -E sh -c'\n        elif command_exists su; then\n            sh_c='su -c'\n        else\n            echo \"Error: this installer needs the ability to run commands as root.\"\n            echo \"We are unable to find either 'sudo' or 'su' available to make this happen.\"\n            exit 1\n        fi\n    fi\n    echo \"# Using command executor: $sh_c\"\n}\n\n# Refine distribution version detection based on the distro\nrefine_distribution_version() {\n    case \"$lsb_dist\" in\n        ubuntu)\n            if command_exists lsb_release; then\n                dist_version=\"$(lsb_release --codename | cut -f2)\"\n            fi\n            if [ -z \"$dist_version\" ] && [ -r /etc/lsb-release ]; then\n                \n                dist_version=\"$(. /etc/lsb-release && echo \"$DISTRIB_CODENAME\")\"\n            fi\n        ;;\n\n        debian|raspbian)\n            # If we only have a number, map it to a codename for better recognition\n            if echo \"$dist_version\" | grep -qE '^[0-9]+$'; then\n                case \"$dist_version\" in\n                    14)\n                        dist_version=\"forky\"\n                    ;;\n                    13)\n                        dist_version=\"trixie\"\n                    ;;\n                    12)\n                        dist_version=\"bookworm\"\n                    ;;\n                    11)\n                        dist_version=\"bullseye\"\n                    ;;\n                    10)\n                        # Handle special case for Buster\n                        dist_version=\"buster\"\n                        if [ \"$user\" = 'root' ]; then\n                            apt-get update --allow-releaseinfo-change || true\n                        elif command_exists sudo; then\n                            sudo apt-get update --allow-releaseinfo-change || true\n                        fi\n                    ;;\n                    9)\n                        dist_version=\"stretch\"\n                    ;;\n                    8)\n                        dist_version=\"jessie\"\n                    ;;\n                    7)\n                        dist_version=\"wheezy\"\n                    ;;\n                esac\n            fi\n        ;;\n\n        centos|rhel|fedora|ol)\n            # Make sure we have a version number\n            if [ -z \"$dist_version\" ] && [ -r /etc/os-release ]; then\n                \n                dist_version=\"$(. /etc/os-release && echo \"$VERSION_ID\")\"\n            fi\n            if [ -z \"$dist_version\" ] && [ -r /etc/redhat-release ]; then\n                dist_version=\"$(sed 's/.*release \\([0-9.]*\\).*/\\1/' /etc/redhat-release)\"\n            fi\n        ;;\n\n        sles|opensuse)\n            if [ -z \"$dist_version\" ] && [ -r /etc/os-release ]; then\n                dist_version=\"$(. /etc/os-release && echo \"$VERSION_ID\")\"\n            fi\n            # Fallback for older versions\n            if [ -z \"$dist_version\" ] && [ -r /etc/SuSE-release ]; then\n                dist_version=\"$(grep VERSION /etc/SuSE-release | sed 's/^VERSION = //')\"\n            fi\n            # Ensure version is in the correct format (e.g., 15.4 for SLES 15 SP4)\n            if [ -n \"$dist_version\" ]; then\n                # Remove any non-numeric characters except dots\n                dist_version=\"$(echo \"$dist_version\" | sed 's/[^0-9.]//g')\"\n            fi\n            # Normalize distribution name\n            if [ \"$lsb_dist\" = \"sles\" ]; then\n                lsb_dist=\"sles\"\n            elif [ \"$lsb_dist\" = \"opensuse\" ]; then\n                lsb_dist=\"opensuse\"\n            fi\n        ;;\n\n        *)\n            if command_exists lsb_release; then\n                dist_version=\"$(lsb_release --release | cut -f2)\"\n            fi\n            if [ -z \"$dist_version\" ] && [ -r /etc/os-release ]; then\n                \n                dist_version=\"$(. /etc/os-release && echo \"$VERSION_ID\")\"\n            fi\n        ;;\n    esac\n}\n\n# Detect init system \ndetect_init_system() {\n    if command -v systemctl >/dev/null 2>&1 && [ -d /etc/systemd/system ]; then\n        INIT_SYSTEM=\"systemd\"\n    elif [ -f /sbin/init ] && /sbin/init --version 2>/dev/null | grep -q upstart; then\n        INIT_SYSTEM=\"upstart\"\n    elif command -v openrc >/dev/null 2>&1 || [ -f /sbin/openrc ]; then\n        INIT_SYSTEM=\"openrc\"\n    elif [ -d /etc/s6 ] || command -v s6-svc >/dev/null 2>&1; then\n        INIT_SYSTEM=\"s6\"\n    elif command -v runit >/dev/null 2>&1 || [ -d /etc/runit ]; then\n        INIT_SYSTEM=\"runit\"\n    elif [ -d /etc/init.d ]; then\n        INIT_SYSTEM=\"sysvinit\"\n    else\n        INIT_SYSTEM=\"unknown\"\n    fi\n    export INIT_SYSTEM\n    echo \"# Detected init system: $INIT_SYSTEM\"\n}\n\n# Detect package type (deb, rpm, or other)\ndetect_package_type() {\n    case \"$lsb_dist\" in\n        debian|ubuntu|raspbian|mendel)\n            PACKAGE_TYPE=\"deb\"\n            ;;\n        fedora|centos|rhel|ol|sles|opensuse*)\n            PACKAGE_TYPE=\"rpm\"\n            ;;\n        alpine)\n            PACKAGE_TYPE=\"apk\"\n            ;;\n        *)\n            if command_exists apt-get || command_exists dpkg; then\n                PACKAGE_TYPE=\"deb\"\n            elif command_exists yum || command_exists dnf || command_exists zypper; then\n                PACKAGE_TYPE=\"rpm\"\n            elif command_exists apk; then\n                PACKAGE_TYPE=\"apk\"\n            else\n                PACKAGE_TYPE=\"other\"\n            fi\n            ;;\n    esac\n    export PACKAGE_TYPE\n    echo \"# Detected package type: $PACKAGE_TYPE\"\n}\n\n# Init function\ninit() {\n    # Detect basic distribution info\n    get_distribution\n    \n    # Set up sudo for privileged commands\n    setup_sudo\n    \n    # Refine version information\n    refine_distribution_version\n    \n    # Check if this is a forked distro\n    check_forked\n    \n    # Detect init system and package type (for universal OS/init support)\n    detect_init_system\n    detect_package_type\n    \n    # Print final distribution information\n    echo \"----------------------------------------\"\n    echo \"Linux Distribution: $lsb_dist\"\n    echo \"Version: $dist_version\"\n    echo \"Init system: $INIT_SYSTEM\"\n    echo \"Package type: $PACKAGE_TYPE\"\n    echo \"----------------------------------------\"\n    \n}\n"),
	}
	filed := &embedded.EmbeddedFile{
		Filename:    "airgap-agent/install_container_engine.sh",
		FileModTime: time.Unix(1774969763, 0),

		Content: string("#!/bin/sh\n# Script to configure Docker/Podman for airgap deployment\n# Check-only: verifies container engine is installed (Docker 25+ or Podman 4+), then configures/starts\n# Sources init.sh for distribution detection\n\nset -x\nset -e\n\nCONTAINER_ENGINE_MSG=\"This operating system does not support automatic container engine installation. Please install Docker 25+ or Podman 4+ on the target host and re-run, or use an airgap deployment with a pre-installed engine.\"\n\ncheck_docker_version() {\n    docker_version_num=0\n    if command -v docker >/dev/null 2>&1; then\n        raw=$(docker -v 2>/dev/null | sed 's/.*version \\([^,]*\\),.*/\\1/' | tr -d '.')\n        [ -n \"$raw\" ] && docker_version_num=\"$raw\"\n    fi\n    [ \"$docker_version_num\" -ge 2500 ] 2>/dev/null || return 1\n}\n\ncheck_podman_version() {\n    podman_version_num=0\n    if command -v podman >/dev/null 2>&1; then\n        raw=$(podman --version 2>/dev/null | sed -n 's/.*version \\([0-9][0-9]*\\).*/\\1/p')\n        [ -n \"$raw\" ] && podman_version_num=\"$raw\"\n    fi\n    [ \"$podman_version_num\" -ge 4 ] 2>/dev/null || return 1\n}\n\nstart_docker() {\n    set +e\n    if $sh_c \"docker ps\" >/dev/null 2>&1; then\n        set -e\n        return 0\n    fi\n    err_code=1\n    case \"${INIT_SYSTEM:-unknown}\" in\n        systemd) $sh_c \"systemctl start docker\" >/dev/null 2>&1; err_code=$? ;;\n        sysvinit) $sh_c \"service docker start\" >/dev/null 2>&1 || $sh_c \"/etc/init.d/docker start\" >/dev/null 2>&1; err_code=$? ;;\n        openrc) $sh_c \"rc-service docker start\" >/dev/null 2>&1; err_code=$? ;;\n        *)\n            $sh_c \"/etc/init.d/docker start\" >/dev/null 2>&1\n            err_code=$?\n            [ $err_code -ne 0 ] && $sh_c \"systemctl start docker\" >/dev/null 2>&1 && err_code=0\n            [ $err_code -ne 0 ] && $sh_c \"service docker start\" >/dev/null 2>&1 && err_code=0\n            [ $err_code -ne 0 ] && $sh_c \"snap start docker\" >/dev/null 2>&1 && err_code=0\n            ;;\n    esac\n    set -e\n    if [ $err_code -ne 0 ]; then\n        echo \"Could not start Docker daemon\"\n        exit 1\n    fi\n}\n\nstart_podman() {\n    set +e\n    case \"${INIT_SYSTEM:-unknown}\" in\n        systemd)\n            $sh_c \"systemctl start podman\" >/dev/null 2>&1\n            $sh_c \"systemctl start podman.socket\" >/dev/null 2>&1\n            ;;\n        sysvinit) $sh_c \"service podman start\" >/dev/null 2>&1 || $sh_c \"/etc/init.d/podman start\" >/dev/null 2>&1 ;;\n        openrc) $sh_c \"rc-service podman start\" >/dev/null 2>&1 ;;\n        *)\n            $sh_c \"systemctl start podman\" >/dev/null 2>&1 || true\n            $sh_c \"systemctl start podman.socket\" >/dev/null 2>&1 || true\n            $sh_c \"service podman start\" >/dev/null 2>&1 || true\n            ;;\n    esac\n    set -e\n}\n\ndo_modify_daemon() {\n    # Skip for Podman installations\n    if [ \"$USE_PODMAN\" = \"true\" ]; then\n        echo \"# Configuring Podman for CDI directory support...\"\n\n        # Create CDI directories\n        $sh_c \"mkdir -p /etc/cdi /var/run/cdi\"\n\n        # Ensure /etc/containers exists\n        $sh_c \"mkdir -p /etc/containers\"\n\n        # Create containers.conf if it doesn't exist\n        if [ ! -f \"/etc/containers/containers.conf\" ]; then\n            $sh_c 'cat > /etc/containers/containers.conf <<EOF\n[engine]\nruntime = \"crun\"\ncdi_spec_dirs = [\"/etc/cdi\", \"/var/run/cdi\"]\nEOF'\n        else\n            # Check if [engine] block exists\n            if grep -q \"^\\[engine\\]\" /etc/containers/containers.conf; then\n                # Ensure runtime is set under [engine]\n                if grep -q \"^runtime\" /etc/containers/containers.conf; then\n                    $sh_c \"sed -i 's|^runtime *=.*|runtime = \\\"crun\\\"|' /etc/containers/containers.conf\"\n                else\n                    $sh_c \"sed -i '/^\\[engine\\]/a runtime = \\\"crun\\\"' /etc/containers/containers.conf\"\n                fi\n\n                # Ensure cdi_spec_dirs is set under [engine]\n                if grep -q \"^cdi_spec_dirs\" /etc/containers/containers.conf; then\n                    $sh_c \"sed -i 's|^cdi_spec_dirs *=.*|cdi_spec_dirs = [\\\"/etc/cdi\\\", \\\"/var/run/cdi\\\"]|' /etc/containers/containers.conf\"\n                else\n                    $sh_c \"sed -i '/^\\[engine\\]/a cdi_spec_dirs = [\\\"/etc/cdi\\\", \\\"/var/run/cdi\\\"]' /etc/containers/containers.conf\"\n                fi\n            else\n                # Append full engine block if missing\n                $sh_c 'echo -e \"\\n[engine]\\nruntime = \\\"crun\\\"\\ncdi_spec_dirs = [\\\"/etc/cdi\\\", \\\"/var/run/cdi\\\"]\" >> /etc/containers/containers.conf'\n            fi\n        fi\n\n        case \"${INIT_SYSTEM:-unknown}\" in\n            systemd)\n                $sh_c \"systemctl enable podman\" 2>/dev/null || true\n                $sh_c \"systemctl enable podman.socket\" 2>/dev/null || true\n                ;;\n            openrc) $sh_c \"rc-update add podman default\" 2>/dev/null || true ;;\n            sysvinit) $sh_c \"update-rc.d podman defaults\" 2>/dev/null || $sh_c \"chkconfig podman on\" 2>/dev/null || true ;;\n            *) ;;\n        esac\n        start_podman\n        return\n    fi\n    \n    # Original Docker daemon configuration\n    if [ ! -f /etc/docker/daemon.json ]; then\n        echo \"Creating /etc/docker/daemon.json...\"\n        $sh_c \"mkdir -p /etc/docker\"\n        $sh_c 'cat > /etc/docker/daemon.json << EOF\n{\n\t\"storage-driver\": \"overlayfs\",\n    \"features\": {\n        \"containerd-snapshotter\": true,\n        \"cdi\": true\n    },\n    \"cdi-spec-dirs\": [\"/etc/cdi/\", \"/var/run/cdi\"]\n}\nEOF'\n    else\n        echo \"/etc/docker/daemon.json already exists\"\n    fi\n    echo \"Restarting Docker daemon...\"\n    case \"${INIT_SYSTEM:-unknown}\" in\n        systemd)\n            $sh_c \"systemctl daemon-reload\"\n            $sh_c \"systemctl restart docker\"\n            ;;\n        *)\n            $sh_c \"systemctl daemon-reload\" 2>/dev/null || true\n            $sh_c \"systemctl restart docker\" 2>/dev/null || start_docker\n            ;;\n    esac\n}\n\n# Airgap: determine engine by availability (Docker 25+ or Podman 4+)\ndetermine_container_engine() {\n    if check_docker_version; then\n        USE_PODMAN=\"false\"\n        echo \"# Using Docker (25+)\"\n    elif check_podman_version; then\n        USE_PODMAN=\"true\"\n        echo \"# Using Podman (4+)\"\n    else\n        echo \"Error: Docker 25+ or Podman 4+ is required. $CONTAINER_ENGINE_MSG\"\n        exit 1\n    fi\n}\n\n. /etc/iofog/agent/init.sh\ninit\n\ndetermine_container_engine\n\n# Start engine and configure\nif [ \"$USE_PODMAN\" = \"false\" ]; then\n    start_docker\nfi\n\ndo_modify_daemon\n\necho \"# Container engine configuration completed successfully\"\n\n"),
	}
